inline const char* tooltipFor (const char* id) noexcept
{
    for (const auto& h : help) if (std::strcmp (h.id, id) == 0) return h.tooltip;
    return "";
}
inline const char* meaningFor (const char* id) noexcept
{
    for (const auto& h : help) if (std::strcmp (h.id, id) == 0) return h.meaning;
    return "";
}
